"""Build the Russian source audit from authored assessments and pinned inventory."""
import csv
import html
import io
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
F = json.loads((HERE / "audit_facts.json").read_text())
PIN = F["subject_commit"]
GH = f"https://github.com/Mput13/case_championship/blob/{PIN}/"
cards = []


def source(name, status, period, paths, purpose, assessment, integration, links=()):
    cards.append(dict(id=f"S{len(cards)+1:02d}", name=name, status=status, period=period,
                      paths=paths, purpose=purpose, assessment=assessment,
                      integration=integration, links=list(links)))


