def esc(x):
    return html.escape(str(x), quote=True)


def a(label, url):
    return f'<a href="{esc(url)}">{esc(label)}</a>'


def filelink(path):
    return a(path, GH + path)


def p(text):
    return f"<p>{text}</p>"


def table(headers, rows):
    return '<div class="table-wrap" tabindex="0"><table><thead><tr>' + ''.join(f'<th>{h}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in row) + '</tr>' for row in rows) + '</tbody></table></div>'


def example(title, records, fields):
    sio = io.StringIO()
    w = csv.DictWriter(sio, fieldnames=fields, extrasaction="ignore", lineterminator="\n")
    w.writeheader()
    w.writerows(records)
    return f'<h4>{esc(title)}</h4><pre><code>{esc(sio.getvalue())}</code></pre>'


